*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--ink);font-family:'Space Grotesk',sans-serif}
body{user-select:none;touch-action:none}
#game{position:relative;width:100%;height:100%;min-height:420px;overflow:hidden;background:radial-gradient(ellipse at 50% 42%,#303b25 0,#1b261a 46%,#10150e 100%)}
canvas{position:absolute;inset:0;width:100%;height:100%;display:block}
.topbar{position:absolute;z-index:2;top:20px;left:clamp(16px,4vw,48px);right:clamp(16px,4vw,48px);display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}
.brand{display:flex;gap:12px;align-items:center}
.mark{width:38px;height:38px;border:1px solid #a6c76b77;border-radius:12px;display:grid;place-items:center;color:var(--moss);font-size:21px;box-shadow:0 0 25px #a6c76b19}
.title{font-weight:700;font-size:12px;letter-spacing:.24em}
.sub{color:var(--muted);font:9px 'DM Mono',monospace;letter-spacing:.15em;margin-top:4px}
.hud{display:flex;gap:clamp(12px,3vw,34px);text-align:right}
.stat small{display:block;color:var(--muted);font:9px 'DM Mono',monospace;letter-spacing:.15em;margin-bottom:5px}
.stat b{font:600 17px 'DM Mono',monospace}
.stat b em{color:var(--moss);font-style:normal}
.stagebar{position:absolute;z-index:2;top:82px;left:50%;transform:translateX(-50%);width:min(310px,50vw);text-align:center;pointer-events:none}
.stage-label{display:flex;justify-content:space-between;font:9px 'DM Mono',monospace;letter-spacing:.13em;color:#d0d5ae;margin-bottom:6px}
.track{height:4px;border-radius:4px;background:#ffffff1a;overflow:hidden}
.fill{height:100%;width:0;background:linear-gradient(90deg,#8fab54,#e3d68c);transition:width .25s}
.stagehint{font:8px 'DM Mono',monospace;color:#aab18f;margin-top:6px;letter-spacing:.1em}
.bossbar{display:none;position:absolute;z-index:2;top:120px;left:50%;transform:translateX(-50%);width:min(280px,55vw);text-align:center}
.bossbar.show{display:block}
.bossbar .track{height:6px}
.bossfill{height:100%;width:100%;background:linear-gradient(90deg,#c6524e,#f4a16d);transition:width .15s}
.bosslabel{font:9px 'DM Mono',monospace;color:#ffb39a;letter-spacing:.15em;margin-bottom:6px}
.hintline{position:absolute;z-index:2;bottom:20px;left:50%;transform:translateX(-50%);color:#c1c6a2;font:9px 'DM Mono',monospace;letter-spacing:.07em;text-align:center;white-space:nowrap;pointer-events:none}
.key{border:1px solid #d5e5a644;border-radius:4px;padding:3px 6px;margin:0 2px;color:#e8e8ce}
.overlay{position:absolute;z-index:5;inset:0;display:grid;place-items:center;padding:20px;background:#0b1009a8;backdrop-filter:blur(4px);transition:opacity .2s,visibility .2s}
.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}
.card{width:min(470px,100%);padding:clamp(25px,5vw,44px);border:1px solid #d5e5a633;border-radius:18px;background:linear-gradient(145deg,#283323f5,#151d14f7);box-shadow:0 25px 90px #0009;text-align:center;position:relative}
.eyebrow{font:10px 'DM Mono',monospace;color:var(--moss);letter-spacing:.23em;text-transform:uppercase}
.card h1{font-size:clamp(38px,9vw,62px);letter-spacing:-.07em;line-height:.91;margin:14px 0}
.card h1 span{display:block;color:var(--moss)}
.card h2{font-size:32px;letter-spacing:-.04em;margin:13px 0}
.intro{font-size:13px;line-height:1.65;color:#c5c9ad;max-width:355px;margin:0 auto}
.mini{display:flex;justify-content:center;gap:25px;margin:23px 0}
.mini b{display:block;font:15px 'DM Mono',monospace}
.mini small{display:block;font:8px 'DM Mono',monospace;letter-spacing:.13em;color:#a1a78a;margin-top:5px}
.primary{width:100%;height:50px;border:0;border-radius:9px;background:var(--moss);color:#182113;font-weight:700;letter-spacing:.1em;text-transform:uppercase;font-size:11px;cursor:pointer}
.primary:hover{background:#bddb82}
.hint{font:9px 'DM Mono',monospace;color:#a1a78a;margin-top:15px;line-height:1.8}
.upgrade-options{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:22px}
.upgrade{border:1px solid #d5e5a644;background:#ffffff08;border-radius:10px;padding:14px 8px;cursor:pointer;color:var(--ink);min-height:105px}
.upgrade:hover{border-color:var(--moss);background:#a6c76b18}
.upgrade b{display:block;color:var(--moss);font-size:12px;margin:7px 0}
.upgrade small{display:block;color:#bbc1a5;font-size:10px;line-height:1.4}
.toast{position:absolute;z-index:3;top:32%;left:50%;transform:translate(-50%,-6px);font:11px 'DM Mono',monospace;letter-spacing:.14em;color:#f5dc8e;opacity:0;transition:.2s;text-shadow:0 0 15px #e4b466}
.toast.show{opacity:1;transform:translate(-50%,0)}
.touch{display:none;position:absolute;z-index:3;bottom:16px;left:15px;right:15px;justify-content:space-between;align-items:flex-end;pointer-events:none}
.dpad{display:grid;grid-template-columns:repeat(3,43px);grid-template-rows:repeat(2,43px);gap:3px;pointer-events:auto}
.touch button{border:1px solid #d5e5a64d;border-radius:10px;background:#1a2618dc;color:#e8edcf;font:12px 'DM Mono',monospace;touch-action:none}
.dpad button:nth-child(1){grid-column:2}
.dpad button:nth-child(2){grid-column:1;grid-row:2}
.dpad button:nth-child(3){grid-column:2;grid-row:2}
.dpad button:nth-child(4){grid-column:3;grid-row:2}
.acts{display:flex;gap:8px;pointer-events:auto}
.acts button{width:58px;height:58px;border-radius:50%;font-size:9px;color:var(--moss)}
@media(max-width:700px){.topbar{top:max(12px,env(safe-area-inset-top));left:14px;right:14px}
.mark{width:31px;height:31px}
.title{font-size:10px}
.sub{font-size:7px}
.hud{gap:12px}
.stat small{font-size:7px}
.stat b{font-size:14px}
.stagebar{top:70px;width:180px}
.bossbar{top:103px}
.hintline{display:none}
.touch{display:flex}
.card{padding:27px 22px}
.intro{font-size:12px}
.mini{gap:15px}
.upgrade-options{gap:6px}
.upgrade{padding:10px 5px;min-height:115px}
.upgrade small{font-size:9px}
}

